 const axis=Array.from({length:5},(_,i)=>{const py=50+i*60,v=high-i*span/4;return '<line x1="90" x2="890" y1="'+py+'" y2="'+py+'" class="market-gridline"/><text class="market-price-tick" x="78" y="'+(py+4)+'" text-anchor="end">'+esc(quote==='USDT'?new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:3}).format(v):quoteMoney(v,quote))+'</text>'}).join('');
