function holdingView(c){const portfolio=callbacks.holdings?.();if(!portfolio)return '';const aliases={USDC:'usd-coin',USDT:'tether',OP:'optimism',BTC:'bitcoin',ETH:'ethereum',ETH_OP:'ethereum',ETH_BASE:'ethereum',ETH_ARB:'ethereum',ETH_LINEA:'ethereum',ETH_RH:'ethereum',BNB:'binancecoin',SOL:'solana',APT:'aptos',SUI:'sui',POL:'polygon-ecosystem-token',AVAX:'avalanche-2',TRX:'tron',XLM:'stellar',S:'sonic-3',XDAI:'xdai',CELO:'celo',MON:'monad',USDC_ARC:'usd-coin'},native={Bitcoin:'BTC',Ethereum:'ETH',Optimism:'ETH_OP',Base:'ETH_BASE',Arbitrum:'ETH_ARB',Linea:'ETH_LINEA','Robinhood Chain':'ETH_RH','BNB Chain':'BNB',Solana:'SOL',Aptos:'APT',Sui:'SUI',Polygon:'POL',Avalanche:'AVAX',Tron:'TRX',Stellar:'XLM',Sonic:'S',Gnosis:'XDAI',Celo:'CELO',Monad:'MON',Arc:'USDC_ARC'};const ledger=(portfolio.assets||[]).filter(a=>aliases[a.symbol]===c.id&&Number(a.quantity)>0),wallets=(portfolio.wallets||[]).filter(w=>aliases[native[w.chain]]===c.id&&Number(w.snapshot?.quantity)>0);const platforms={Ethereum:'ethereum',Optimism:'optimistic-ethereum','BNB Chain':'binance-smart-chain',Base:'base',Arbitrum:'arbitrum-one',Polygon:'polygon-pos',Avalanche:'avalanche',Sonic:'sonic',Gnosis:'xdai',Celo:'celo',Linea:'linea',Solana:'solana'};const tokens=(portfolio.wallets||[]).flatMap(w=>(w.token_snapshot?.tokens||[]).filter(t=>{const contract=t.contract||t.mint,expected=c.platforms?.[platforms[w.chain]];return typeof contract==='string'&&typeof expected==='string'&&Number(t.quantity)>0&&(w.chain==='Solana'?contract===expected:contract.toLowerCase()===expected.toLowerCase())}));const exchangeSeen=new Set(),exchangeRows=[...(portfolio.exchanges||[])].sort((a,b)=>(Number(b.snapshot?.updated_at)||0)-(Number(a.snapshot?.updated_at)||0)).filter(x=>{const key=x.snapshot?.account_key||x.id;if(key&&exchangeSeen.has(key))return false;if(key)exchangeSeen.add(key);return true}).flatMap(x=>(x.snapshot?.balances||[]).filter(b=>b.coin_id===c.id&&!(b.account_type==='Earn'&&b.valuation_basis!=='verified_earn_underlying')).map(b=>({...b,holding_quantity:b.valuation_basis==='verified_earn_underlying'?b.display_quantity:b.quantity})).filter(b=>valid(b.holding_quantity)&&Number(b.holding_quantity)>0));if(!ledger.length&&!wallets.length&&!exchangeRows.length&&!tokens.length)return '<section class="market-panel market-personal"><h3>Your holdings</h3><p class="market-footnote">No matching native wallet balances or supported ledger assets. Contract tokens require verified identity mapping.</p></section>';const card=(label,quantity,detail)=>{const priced=valid(c.current_price),value=priced?quantity*Number(c.current_price):null,pct=Number(c.price_change_percentage_24h),changeValue=priced&&c.price_change_percentage_24h!=null&&Number.isFinite(pct)&&pct> -100?value-value/(1+pct/100):null;return '<div class="market-detail-stat"><dt>'+esc(label)+'</dt><dd>'+esc(new Intl.NumberFormat('en-US',{maximumSignificantDigits:12}).format(quantity))+' '+esc(c.symbol)+'</dd><strong>'+esc(money(value))+'</strong><small>'+esc(detail)+'</small><small>24h price '+change(c.price_change_percentage_24h)+(changeValue!==null?' · '+esc(new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(changeValue))+' at current quantity':'')+'</small></div>'};return '<section class="market-panel market-personal"><span class="market-eyebrow">YOUR PORTFOLIO</span><h3>Your '+esc(c.name)+'</h3><div class="market-detail-stats">'+(wallets.length?card('Connected wallets',wallets.reduce((a,w)=>a+Number(w.snapshot.quantity),0),wallets.length+' network balances · balance timestamps may differ'):'')+(tokens.length?card('Verified contract holdings',tokens.reduce((a,t)=>a+Number(t.quantity),0),'Matched by provider network and contract/mint identity'):'')+(exchangeRows.length?card('Connected exchange balances',exchangeRows.reduce((a,r)=>a+Number(r.holding_quantity),0),'Synced Spot or verified Flexible Earn amounts; kept separate from your ledger'):'')+(ledger.length?card('Recorded trade holdings',ledger.reduce((a,t)=>a+Number(t.quantity),0),'Cost basis '+money(ledger.reduce((a,t)=>a+Number(t.cost||0),0))):'')+'</div><p class="market-footnote">Wallet, exchange and ledger holdings stay separate because they may describe the same coins. The 24h estimate applies price movement to today’s quantity; it is not your historical return. Save valuation checkpoints in Insights to track observed portfolio history.</p></section>'}
function ledgerControl(quote,fills){const aliases=[...new Set((callbacks.trades?.()||[]).map(t=>t.symbol).filter(x=>typeof x==='string'))].sort();return '<details class="market-provenance"><summary>My recorded buys &amp; sells'+(s.ledgerAlias?' · '+esc(s.ledgerAlias):'')+'</summary><p class="market-footnote">Manually match a recorded ledger asset to this coin only after verifying its identity. Markers show saved executions, not open orders. Unit prices are USD; overlays are disabled for USDT charts.</p><label>Match ledger asset<select data-market-ledger '+(quote!=='USD'?'disabled':'')+'><option value="">No personal trade overlay</option>'+aliases.map(alias=>'<option value="'+esc(alias)+'"'+(s.ledgerAlias===alias?' selected':'')+'>'+esc(alias)+'</option>').join('')+'</select></label><p class="market-footnote">'+(quote!=='USD'?'Choose a USD chart source for recorded fills.':s.ledgerAlias?fills.length+' recorded fills in the visible period · B = buy, S = sell · Most recent 100 shown.':'No automatic ticker matching is applied.')+'</p></details>'}
function visibleRows(){const all=(s.chartType==='candles'?s.chart?.candles:s.chart?.points)||[],count=s.viewCount||all.length;return all.slice(Math.max(0,Math.min(s.viewStart,all.length-count)),Math.max(0,Math.min(s.viewStart,all.length-count))+count)}
function observationText(p,quote,isCandle){return exactDate(p.timestamp,s.timeZone)+' · '+(isCandle?['open','high','low','close'].map(k=>k[0].toUpperCase()+k.slice(1)+' '+quoteMoney(p[k],quote)).join(' · '):'Price '+quoteMoney(p.price,quote))}
function inspection(rows,quote,isCandle){if(s.chartLoading||s.chartError||!rows.length)return '';return '<div class="market-inspection"><span class="market-eyebrow">INSPECT OBSERVATION</span><output data-chart-readout for="marketObservation" aria-live="polite">'+esc(observationText(rows.at(-1),quote,isCandle))+'</output><input id="marketObservation" data-chart-observation type="range" min="0" max="'+(rows.length-1)+'" value="'+(rows.length-1)+'" aria-label="Inspect chart observation"><small>Move across the chart or use this slider for the exact date, time and price.</small></div>'}
function inspectAt(index){const rows=visibleRows();if(!rows.length)return;index=Math.max(0,Math.min(rows.length-1,index));const p=rows[index],quote=s.chart?.quote_currency||(s.chartSource==='binance'?'USDT':'USD'),out=container.querySelector('[data-chart-readout]'),slider=container.querySelector('[data-chart-observation]'),cross=container.querySelector('[data-chart-crosshair]');if(out)out.textContent=observationText(p,quote,s.chartType==='candles');if(slider)slider.value=index;if(cross){const span=Number(rows.at(-1).timestamp)-Number(rows[0].timestamp)||1,x=90+(Number(p.timestamp)-Number(rows[0].timestamp))/span*800;const scale=Number(container.querySelector('svg.market-chart')?.dataset?.plotScale)||1;cross.setAttribute('x1',fitChartX(x,scale));cross.setAttribute('x2',fitChartX(x,scale))}}
function zoomControls(loaded,start,count){if(s.chartLoading||s.chartError||!loaded.length)return '';const end=start+count,min=Math.min(5,loaded.length);return '<div class="market-zoom" role="group" aria-label="Chart zoom and navigation"><button data-market-zoom="in" '+(count<=min?'disabled':'')+' aria-label="Zoom in on chart">Zoom in +</button><button data-market-zoom="out" '+(count>=loaded.length?'disabled':'')+' aria-label="Zoom out on chart">Zoom out −</button><button data-market-zoom="reset" '+(count===loaded.length?'disabled':'')+'>Reset zoom</button><button data-market-pan="earlier" '+(start===0?'disabled':'')+'>← Earlier</button><button data-market-pan="later" '+(end>=loaded.length?'disabled':'')+'>Later →</button><p class="market-footnote" role="status">Showing '+count+' of '+loaded.length+' loaded observations · '+esc(exactDate(loaded[start].timestamp,s.timeZone))+' — '+esc(exactDate(loaded[end-1].timestamp,s.timeZone))+'. Zoom uses loaded data; no additional fetch.</p></div>'}
function zoom(action){const rows=(s.chartType==='candles'?s.chart?.candles:s.chart?.points)||[];if(s.chartLoading||!rows.length)return;const count=s.viewCount||rows.length,min=Math.min(5,rows.length),next=action==='reset'?rows.length:action==='in'?Math.max(min,Math.floor(count/2)):Math.min(rows.length,count*2),center=s.viewStart+count/2;s.viewCount=next;s.viewStart=action==='reset'?0:Math.max(0,Math.min(rows.length-next,Math.round(center-next/2)));render();container.querySelector('[data-market-zoom="'+action+'"]')?.focus()}
function pan(direction){const rows=(s.chartType==='candles'?s.chart?.candles:s.chart?.points)||[],count=s.viewCount||rows.length;s.viewStart=Math.max(0,Math.min(rows.length-count,s.viewStart+(direction==='earlier'?-1:1)*Math.max(1,Math.floor(count/2))));render();container.querySelector('[data-market-pan="'+direction+'"]')?.focus()}
function newsView(){const n=s.news;return '<section class="market-panel"><div class="market-panel-head"><div><span class="market-eyebrow">FOLLOW THE PROJECT</span><h3>Coin news</h3></div><button data-market-news '+(s.newsLoading?'disabled':'')+'>'+(s.newsLoading?'Loading…':n?'Refresh news':'Load news')+'</button></div>'+(s.newsLoading?'<p role="status">Fetching source headlines…</p>':s.newsError?'<p class="market-warning" role="status">'+esc(s.newsError)+' Try loading news again.</p>':n?banner(n)+(n.articles?.length?'<ul class="market-news-list">'+n.articles.map(a=>{const title=link(a.url,a.title);return title?'<li>'+title+'<small>'+esc(a.source||n.source||'Publisher')+' · '+esc(stamp(a.published_at))+'</small></li>':''}).join('')+'</ul>':'<p class="market-muted-state">'+(n.available===false?'Public news is temporarily unavailable. Use the news search link below.':'No matching headlines were returned for this coin.')+'</p>')+'<p class="market-footnote">'+esc(n.coverage||'Provider-selected headlines; coverage is not exhaustive.')+' Retrieved '+esc(stamp(n.fetched_at))+'.</p><div class="market-links">'+(n.search_links||[]).map(x=>link(x.url,x.label||'Search news')).join('')+'</div>':'<p class="market-muted-state">Read the latest coverage on Google News, or load available public-index headlines. Articles open on their publisher’s website.</p>'+link('https://news.google.com/search?q='+encodeURIComponent((s.detail?.coin?.name||s.selected)+' cryptocurrency'),'Read latest coin news')+'')+'</section>'}
async function loadNews(){const id=s.selected,token=s.seq,seq=++s.newsSeq;s.newsLoading=true;s.newsError='';render();try{if(!callbacks.news)throw Error('News service is not configured.');const data=await callbacks.news(id);if(s.seq===token&&s.selected===id&&s.newsSeq===seq)s.news=data}catch(e){if(s.seq===token&&s.newsSeq===seq)s.newsError=e.message||'News unavailable'}finally{if(s.seq===token&&s.newsSeq===seq){s.newsLoading=false;render()}}}
function revenueView(){const r=s.fund?.revenue;return '<section class="market-panel"><span class="market-eyebrow">PROTOCOL FUNDAMENTALS</span><h3>Reported revenue</h3>'+(s.fundLoading?'<p role="status">Loading source-verified protocol data…</p>':r?.available?'<p>'+esc(r.protocol)+'</p><dl class="market-detail-stats">'+stat('Latest reported 24h',money(r.day_usd))+stat('Reported 7 days',money(r.week_usd))+stat('Reported 30 days',money(r.month_usd))+'</dl><p class="market-footnote">'+esc(r.definition)+'</p>'+'<p class="market-footnote">Retrieved '+esc(stamp(r.fetched_at))+(r.stale?' · Cached data; provider unavailable':'')+'</p>'+link(r.source_url,'DefiLlama source'):'<p class="market-muted-state">'+esc(r?.message||s.fundError||'Revenue data has not been loaded.')+'</p>')+'</section>'}
function unlocksView(){const u=s.fund?.unlocks;return '<section class="market-panel"><span class="market-eyebrow">EMISSIONS &amp; VESTING</span><h3>Token unlocks</h3>'+(s.fundLoading?'<p role="status">Checking unlock-data availability…</p>':u?.available?'<dl class="market-detail-stats">'+stat('Reported locked tokens',amount(u.locked_tokens))+stat('Reported unlocks per day',amount(u.unlocks_per_day))+'</dl>'+(u.events?.length?'<ul>'+u.events.map(e=>'<li>'+esc(stamp(e.timestamp))+' · '+esc(e.description)+'</li>').join('')+'</ul>':'')+'<p class="market-footnote">'+esc(u.message)+'</p><p class="market-footnote">Retrieved '+esc(stamp(u.fetched_at))+(u.stale?' · Cached data; provider unavailable':'')+'</p>'+link(u.source_url,'Unlock provider'):'<p class="market-muted-state">'+esc(u?.message||s.fundError||'No verified unlock schedule available.')+'</p>'+link('https://defillama.com/unlocks','View provider coverage'))+'<p class="market-footnote">A missing schedule does not mean no future unlocks. Scheduled token release is different from circulating-supply growth.</p></section>'}
async function loadList(){s.loading=true;s.error='';render();try{s.list=await callbacks.listings()}catch(e){s.error=e.message||'Market provider unavailable';callbacks.error?.(s.error)}finally{s.loading=false;render()}}
async function refreshMarketQuote(force=false){if(!callbacks.quote||!s.selected||s.quoteBusy)return;const interval=Math.max(s.chartSource==='coingecko'?60000:5000,s.quoteBackoff);if(!force&&Date.now()-s.quoteAttempt<interval)return;const id=s.selected,source=s.chartSource,token=s.seq,chartToken=s.chartSeq;s.quoteBusy=true;s.quoteAttempt=Date.now();try{const q=await callbacks.quote(id,source);if(id!==s.selected||source!==s.chartSource||token!==s.seq||chartToken!==s.chartSeq)return;const unit=source==='binance'?'USDT':'USD';if(q.coin_id!==id||q.quote_currency!==unit||!valid(q.price)||Number(q.price)<=0)throw Error('Quote identity mismatch');s.quote=q;s.quoteError='';s.quoteBackoff=0;if(source==='coingecko'&&!q.stale&&s.detail?.coin){s.detail.coin.current_price=q.price;const head=container.querySelector('.market-main-price');if(head)head.textContent=money(q.price)}const svg=container.querySelector('svg.market-chart'),reference=svg?.querySelector?.('[data-market-reference]');if(reference)reference.innerHTML=priceReference(Number(q.price),unit,Number(svg.dataset.scaleLow),Number(svg.dataset.scaleHigh),q.stale?'Cached quote':'Current price',Number(svg.dataset.plotScale)||1,Number(svg.dataset.plotHeightScale)||1)}catch(e){if(id===s.selected&&source===s.chartSource&&token===s.seq&&chartToken===s.chartSeq){s.quoteError='Refresh unavailable';s.quoteBackoff=30000;if(s.quote)s.quote={...s.quote,stale:true}}}finally{s.quoteBusy=false;if(id===s.selected&&source===s.chartSource&&token===s.seq){const host=container.querySelector('[data-market-quote]');if(host)host.innerHTML=quoteStatus()}}}
